using Unity.Burst;
using Unity.Collections;
using Unity.Jobs;
using Unity.Mathematics;

[BurstCompile]
struct HealJob : IJobFor
{
    public NativeArray<float> hp;
    [ReadOnly] public NativeArray<float> regen;
    public float dt, maxHp;

    public void Execute(int i)
    {
        hp[i] = math.min(hp[i] + regen[i] * dt, maxHp);
    }
}

static class Healing
{
    public static JobHandle Schedule(NativeArray<float> hp, NativeArray<float> regen,
                                     float dt, float maxHp, JobHandle dependsOn)
    {
        var job = new HealJob { hp = hp, regen = regen, dt = dt, maxHp = maxHp };
        return job.ScheduleParallel(hp.Length, 64, dependsOn);   // many workers, batches of 64
    }
}

