using Unity.Burst;
using Unity.Collections;
using Unity.Jobs;
using UnityEngine;
using UnityEngine.Jobs;

public class Mover : MonoBehaviour
{
    TransformAccessArray transforms;     // filled in Awake
    NativeArray<Vector3> velocity;       // Allocator.Persistent
    JobHandle handle;

    void Update()
    {
        var job = new VelocityJob { velocity = velocity, dt = Time.deltaTime };
        handle = job.Schedule(transforms);
        JobHandle.ScheduleBatchedJobs();   // wake the workers now
    }

    void LateUpdate()
    {
        handle.Complete();                 // the transforms are written by now
    }
}

[BurstCompile]
struct VelocityJob : IJobParallelForTransform
{
    [ReadOnly] public NativeArray<Vector3> velocity;
    public float dt;

    public void Execute(int index, TransformAccess transform)
    {
        transform.position += velocity[index] * dt;
    }
}

